    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)
    visited = [[False]*cols for _ in range(rows)]
    rects = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                ce = c
                while ce+1 < cols and grid[r][ce+1] == color: ce += 1
                re = r
                while re+1 < rows and all(grid[re+1][cc] == color for cc in range(c, ce+1)): re += 1
                for rr in range(r, re+1):
                    for cc in range(c, ce+1): visited[rr][cc] = True
                rects.append((color, r, re, c, ce))
    for i in range(len(rects)):
        for j in range(i+1, len(rects)):
            c1,r1a,r1b,c1a,c1b = rects[i]
            c2,r2a,r2b,c2a,c2b = rects[j]
            if c1 != c2: continue
            roa,rob = max(r1a,r2a), min(r1b,r2b)
            if roa <= rob:
                if c1b < c2a:
                    ga,gb = c1b+1, c2a-1
                elif c2b < c1a:
                    ga,gb = c2b+1, c1a-1
