                if ga <= gb:
                    clear = all(grid[rr][cc]==0 for rr in range(roa,rob+1) for cc in range(ga,gb+1))
                    if clear and roa+1<=rob-1:
                        for rr in range(roa+1,rob):
                            for cc in range(ga,gb+1): output[rr][cc]=8
            coa,cob = max(c1a,c2a), min(c1b,c2b)
