def transform(grid):
    rows, cols = len(grid), len(grid[0])
    five_cells = {(r,c) for r in range(rows) for c in range(cols) if grid[r][c]==5}

    # Extract legend: color markers not in 5-blocks, with 2x2 pattern at offset (+1,+1)
    color_patterns = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v not in (0,1,5) and (r,c) not in five_cells:
                # Check if near 1-patterns (legend entry)
                has_ones = False
                for dr in range(1,3):
                    for dc in range(1,3):
                        if 0<=r+dr<rows and 0<=c+dc<cols and grid[r+dr][c+dc]==1:
                            has_ones = True
                if has_ones:
                    pat = []
                    for dr in range(1,3):
                        row_p = []
                        for dc in range(1,3):
                            nr, nc = r+dr, c+dc
                            row_p.append(grid[nr][nc] if 0<=nr<rows and 0<=nc<cols else 0)
                        pat.append(row_p)
                    color_patterns[v] = pat

    if not five_cells:
        return grid

    min_r = min(r for r,c in five_cells)
    max_r = max(r for r,c in five_cells)
    min_c = min(c for r,c in five_cells)
    max_c = max(c for r,c in five_cells)

    block_rows, r = [], min_r
    while r <= max_r:
        if any((r,c) in five_cells for c in range(min_c, max_c+1)):
            block_rows.append(r); r += 3
        else:
            r += 1

    block_cols, c = [], min_c
    while c <= max_c:
        if any((r,c) in five_cells for r in range(min_r, max_r+1)):
            block_cols.append(c); c += 3
        else:
            c += 1

    num_br, num_bc = len(block_rows), len(block_cols)
    block_colors = [[0]*num_bc for _ in range(num_br)]
    for bi, br in enumerate(block_rows):
        for bj, bc in enumerate(block_cols):
            for dr in range(2):
                for dc in range(2):
                    v = grid[br+dr][bc+dc]
                    if v != 5 and v != 0:
                        block_colors[bi][bj] = v

    out_rows = num_br*2 + (num_br-1)
    out_cols = num_bc*2 + (num_bc-1)
    output = [[0]*out_cols for _ in range(out_rows)]

    for bi in range(num_br):
        for bj in range(num_bc):
            color = block_colors[bi][bj]
            if color == 0: continue
            pat = color_patterns.get(color, [[0,0],[0,0]])
            or_, oc = bi*3, bj*3
            for dr in range(2):
                for dc in range(2):
                    if pat[dr][dc] == 1:
                        output[or_+dr][oc+dc] = color
    return output

def transform(grid):
    import copy
    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)
    ones = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c]==1]
    h_lines, v_lines = set(), set()
    for i in range(len(ones)):
        for j in range(i+1, len(ones)):
            if ones[i][0]==ones[j][0]: h_lines.add(ones[i][0])
            if ones[i][1]==ones[j][1]: v_lines.add(ones[i][1])
    visited = [[False]*cols for _ in range(rows)]
    rectangles = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]==2 and not visited[r][c]:
                queue, cells = [(r,c)], [(r,c)]
                visited[r][c] = True
                while queue:
                    cr,cc = queue.pop(0)
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and grid[nr][nc]==2:
                            visited[nr][nc]=True; queue.append((nr,nc)); cells.append((nr,nc))
                rectangles.append(cells)
    for rect in rectangles:
        rrows = set(r for r,c in rect); rcols = set(c for r,c in rect)
        if any(h in rrows for h in h_lines) or any(v in rcols for v in v_lines):
            for r,c in rect: output[r][c] = 1
    for h in h_lines:
        for c in range(cols): output[h][c] = 1
    for v in v_lines:
        for r in range(rows): output[r][v] = 1
    return output

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    objects = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and grid[nr][nc]==color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                objects.append((color, cells))
    objects.sort(key=lambda obj: max(c for r,c in obj[1]), reverse=True)
    output = [[0]*cols for _ in range(rows)]
    for color, cells in objects:
        max_shift = min(cols-1-c for r,c in cells)
        best_shift = 0
        for shift in range(max_shift, -1, -1):
            valid = all(output[r][c+shift]==0 for r,c in cells)
            if valid:
                best_shift = shift
                break
        for r,c in cells:
            output[r][c+best_shift] = color
    return output

def transform(grid):
    import copy
    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)

    corners = [(0,0),(0,cols-2),(rows-2,0),(rows-2,cols-2)]
    for r0,c0 in corners:
        if all(grid[r0+dr][c0+dc] != 8 for dr in range(2) for dc in range(2)):
            key = [[grid[r0+dr][c0+dc] for dc in range(2)] for dr in range(2)]
            if r0 == 0 and c0 == 0:
                gr_s, gc_s, gr_e, gc_e = 2, 2, rows-1, cols-1
            elif r0 == 0 and c0 == cols-2:
                gr_s, gc_s, gr_e, gc_e = 2, 0, rows-1, cols-3
            elif r0 == rows-2 and c0 == 0:
                gr_s, gc_s, gr_e, gc_e = 0, 2, rows-3, cols-1
            else:
                gr_s, gc_s, gr_e, gc_e = 0, 0, rows-3, cols-3
            break

    grid_rows = gr_e - gr_s + 1
    grid_cols = gc_e - gc_s + 1
    mid_r = gr_s + grid_rows // 2
    mid_c = gc_s + grid_cols // 2

    for r in range(gr_s, gr_e+1):
        for c in range(gc_s, gc_e+1):
            if grid[r][c] == 1:
                qi = 0 if r < mid_r else 1
                qj = 0 if c < mid_c else 1
                output[r][c] = key[qi][qj]
    return output

