def transform(grid):
    rows, cols = len(grid), len(grid[0])
    fours = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c]==4]
    min_r = min(r for r,c in fours); max_r = max(r for r,c in fours)
    min_c = min(c for r,c in fours); max_c = max(c for r,c in fours)
    h, w = max_r-min_r+1, max_c-min_c+1

    six_pos = frozenset((r-min_r, c-min_c) for r in range(min_r,max_r+1) for c in range(min_c,max_c+1) if grid[r][c]==6)

    transforms = set()
    pos = six_pos; ch, cw = h, w
    for _ in range(4):
        transforms.add((pos, ch, cw))
        transforms.add((frozenset((r, cw-1-c) for r,c in pos), ch, cw))
        pos = frozenset((c, ch-1-r) for r,c in pos)
        ch, cw = cw, ch

    output = copy.deepcopy(grid)
    for t_pos, th, tw in transforms:
        for r in range(rows-th+1):
            for c in range(cols-tw+1):
                if r==min_r and c==min_c: continue
                block_sixes = frozenset((dr,dc) for dr in range(th) for dc in range(tw) if grid[r+dr][c+dc]==6)
                if block_sixes == t_pos:
                    for dr in range(th):
                        for dc in range(tw):
                            if grid[r+dr][c+dc] != 6:
                                output[r+dr][c+dc] = 4
    return output

