def transform(grid):
    grid = [list(row) for row in grid]
    out = copy.deepcopy(grid)
    R, C = len(grid), len(grid[0])

    start = None
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 2:
                start = (r, c)

    hwall = [r for r in range(R) if sum(1 for c in range(C) if grid[r][c]==8) > C//2]
    vwall = [c for c in range(C) if sum(1 for r in range(R) if grid[r][c]==8) > R//2]

    if len(hwall) >= len(vwall):
        wset = set(hwall)
        gaps = {wr: [c for c in range(C) if grid[wr][c]==0] for wr in hwall}

        def go(entries, row, d):
            r = row
            while 0 <= r < R and r not in wset:
                r += d
            if r < 0 or r >= R:
                for ec in entries:
                    rr = row
                    while 0 <= rr < R:
                        out[rr][ec] = 2; rr += d
                return
            wr = r
            wset.discard(wr)
            g = gaps[wr]
            for ec in entries:
                rr = row
                while rr != wr:
                    out[rr][ec] = 2; rr += d
            mn, mx = None, None
            for ec in entries:
                left = None; right = None
                for gc in g:
                    if gc <= ec and (left is None or gc > left): left = gc
                    if gc >= ec and (right is None or gc < right): right = gc
                lo = left if left is not None else 0
                hi = right if right is not None else C-1
                if mn is None or lo < mn: mn = lo
                if mx is None or hi > mx: mx = hi
            for gc in g:
                if mn <= gc <= mx:
                    pass
                else:
                    pass
            all_c = sorted(set(g + entries))
            real_min = mn; real_max = mx
            for ec in entries:
                fl = any(gc <= ec for gc in g)
                fr = any(gc >= ec for gc in g)
                if not fl: real_min = 0
                if not fr: real_max = C-1
            for gc in g:
                if gc < real_min: real_min = min(real_min, gc)
                if gc > real_max: real_max = max(real_max, gc)
            pre = wr - d
            for c in range(real_min, real_max+1):
                out[pre][c] = 2
            used_gaps = [gc for gc in g if real_min <= gc <= real_max]
            for gc in used_gaps:
                out[wr][gc] = 2
            nxt = wr + d
            if 0 <= nxt < R and used_gaps:
                go(used_gaps, nxt, d)

        go([start[1]], start[0], 1)
    else:
        wset = set(vwall)
        gaps = {wc: [r for r in range(R) if grid[r][wc]==0] for wc in vwall}

        def go(entries, col, d):
            c = col
            while 0 <= c < C and c not in wset:
                c += d
            if c < 0 or c >= C:
                for er in entries:
                    cc = col
                    while 0 <= cc < C:
                        out[er][cc] = 2; cc += d
                return
            wc = c
            wset.discard(wc)
            g = gaps[wc]
            for er in entries:
                cc = col
                while cc != wc:
                    out[er][cc] = 2; cc += d
            real_min = None; real_max = None
            for er in entries:
                up = None; down = None
                for gr in g:
                    if gr <= er and (up is None or gr > up): up = gr
                    if gr >= er and (down is None or gr < down): down = gr
                lo = up if up is not None else 0
                hi = down if down is not None else R-1
                if real_min is None or lo < real_min: real_min = lo
                if real_max is None or hi > real_max: real_max = hi
            for er in entries:
                fu = any(gr <= er for gr in g)
                fd = any(gr >= er for gr in g)
                if not fu: real_min = 0
                if not fd: real_max = R-1
            for gr in g:
                if gr < real_min: real_min = min(real_min, gr)
                if gr > real_max: real_max = max(real_max, gr)
            pre = wc - d
            for r in range(real_min, real_max+1):
                out[r][pre] = 2
            used_gaps = [gr for gr in g if real_min <= gr <= real_max]
            for gr in used_gaps:
                out[gr][wc] = 2
            nxt = wc + d
            if 0 <= nxt < C and used_gaps:
                go(used_gaps, nxt, d)

        go([start[0]], start[1], 1)

    return out

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1+1, rows):
                for c2 in range(c1+1, cols):
                    all_zero = all(grid[r][c] == 0 for r in range(r1, r2+1) for c in range(c1, c2+1))
                    if not all_zero:
                        continue
                    can_extend_up = r1 > 0 and all(grid[r1-1][c] == 0 for c in range(c1, c2+1))
                    can_extend_down = r2 < rows-1 and all(grid[r2+1][c] == 0 for c in range(c1, c2+1))
                    can_extend_left = c1 > 0 and all(grid[r][c1-1] == 0 for r in range(r1, r2+1))
                    can_extend_right = c2 < cols-1 and all(grid[r][c2+1] == 0 for r in range(r1, r2+1))
                    if not (can_extend_up or can_extend_down or can_extend_left or can_extend_right):
                        for r in range(r1, r2+1):
                            for c in range(c1, c2+1):
                                output[r][c] = 1
