def transform(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    blocks = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                stack = [(r, c)]
                visited[r][c] = True
                min_r, max_r, min_c, max_c = r, r, c, c
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                            min_r, max_r = min(min_r, nr), max(max_r, nr)
                            min_c, max_c = min(min_c, nc), max(max_c, nc)
                blocks.append((min_c, color, max_r - min_r + 1, max_c - min_c + 1))
    blocks.sort(key=lambda x: x[0])
    output = [[0]*cols for _ in range(rows)]
    cur_r, cur_c = 0, 0
    for _, color, h, w in blocks:
        for r in range(cur_r, cur_r + h):
            for c in range(cur_c, cur_c + w):
                if 0 <= r < rows and 0 <= c < cols:
                    output[r][c] = color
        cur_r += h - 1
        cur_c += w - 1
    return output

def transform(grid):
    from collections import Counter
    rows, cols = len(grid), len(grid[0])

    row_counts = [sum(1 for c in range(cols) if grid[r][c] != 0) for r in range(rows)]
    col_counts = [sum(1 for r in range(rows) if grid[r][c] != 0) for c in range(cols)]

    row_threshold = max(row_counts) * 0.4
    col_threshold = max(col_counts) * 0.4

    block_rows = []
    in_block = False
    for r in range(rows):
        if row_counts[r] >= row_threshold:
            if not in_block: start = r; in_block = True
        else:
            if in_block: block_rows.append((start, r - 1)); in_block = False
    if in_block: block_rows.append((start, rows - 1))

    block_cols = []
    in_block = False
    for c in range(cols):
        if col_counts[c] >= col_threshold:
            if not in_block: start = c; in_block = True
        else:
            if in_block: block_cols.append((start, c - 1)); in_block = False
    if in_block: block_cols.append((start, cols - 1))

    block_h = block_rows[0][1] - block_rows[0][0] + 1
    block_w = block_cols[0][1] - block_cols[0][0] + 1

    blocks = []
    for rs, re in block_rows:
        for cs, ce in block_cols:
            block = [[grid[r][c] for c in range(cs, ce + 1)] for r in range(rs, re + 1)]
            blocks.append(block)

    canonical = [[0] * block_w for _ in range(block_h)]
    for i in range(block_h):
        for j in range(block_w):
            values = [block[i][j] for block in blocks]
            canonical[i][j] = Counter(values).most_common(1)[0][0]

    output = [[0] * cols for _ in range(rows)]
    for rs, re in block_rows:
        for cs, ce in block_cols:
            for i in range(block_h):
                for j in range(block_w):
                    output[rs + i][cs + j] = canonical[i][j]
    return output

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    ones = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c]==1]
    min_r,max_r = min(r for r,c in ones), max(r for r,c in ones)
    min_c,max_c = min(c for r,c in ones), max(c for r,c in ones)
    pattern = [[grid[r][c] for c in range(min_c,max_c+1)] for r in range(min_r,max_r+1)]
    ph, pw = len(pattern), len(pattern[0])
    colors = [(r,c,grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] not in (0,1)]
    if all(r==colors[0][0] for r,c,v in colors):
        colors.sort(key=lambda x:x[1])
        output = []
        for pr in range(ph):
            row = []
            for _,_,color in colors:
                for pc in range(pw):
                    row.append(color if pattern[pr][pc]==1 else 0)
            output.append(row)
        return output
    else:
        colors.sort(key=lambda x:x[0])
        output = []
        for _,_,color in colors:
            for pr in range(ph):
                row = [color if pattern[pr][pc]==1 else 0 for pc in range(pw)]
                output.append(row)
        return output

def transform(grid):
    import copy
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)

    visited = [[False]*cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1) and grid[r][c] != 8:
                queue.append((r, c))
                visited[r][c] = True
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != 8:
                visited[nr][nc] = True
                queue.append((nr, nc))

    interior_set = set()
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != 8:
                interior_set.add((r, c))

    grouped = []
    visited2 = set()
    for r, c in interior_set:
        if (r, c) not in visited2:
            component = []
            q = deque([(r, c)])
            visited2.add((r, c))
            while q:
                cr, cc = q.popleft()
                component.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if (nr, nc) in interior_set and (nr, nc) not in visited2:
                        visited2.add((nr, nc))
                        q.append((nr, nc))
            grouped.append(component)

    for component in grouped:
        min_r = min(r for r, c in component)
        max_r = max(r for r, c in component)
        min_c = min(c for r, c in component)
        max_c = max(c for r, c in component)
        center_r = (min_r + max_r) / 2.0
        center_c = (min_c + max_c) / 2.0

        twos = [(r, c) for r, c in component if grid[r][c] == 2]
        for r, c in twos:
            nc = int(round(2 * center_c - c))
            nr = int(round(2 * center_r - r))
            output[r][nc] = 2
            output[nr][c] = 2
            output[nr][nc] = 2

    return output

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find the two 2s
    points = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                points.append((r, c))

    (r1, c1), (r2, c2) = points
    min_r, max_r = min(r1, r2), max(r1, r2)
