    # Find connected components of each non-zero color (border candidates)
    visited_border = [[False]*cols for _ in range(rows)]

    def get_border_cells(r, c, color):
        stack = [(r, c)]
        cells = set()
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in cells: continue
            if cr < 0 or cr >= rows or cc < 0 or cc >= cols: continue
            if grid[cr][cc] != color: continue
            cells.add((cr, cc))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                stack.append((cr+dr, cc+dc))
        return cells

    def flood_fill_interior(border_cells, color):
        min_r = min(r for r,c in border_cells)
        max_r = max(r for r,c in border_cells)
        min_c = min(c for r,c in border_cells)
        max_c = max(c for r,c in border_cells)

        interior = set()
        for r in range(min_r, max_r+1):
            for c in range(min_c, max_c+1):
                if (r,c) not in border_cells:
                    interior.add((r,c))

        # Check if interior is enclosed - flood fill from each interior cell, should not reach grid edge
        exterior = set()
        checked = set()

        def is_exterior(r, c):
            if (r,c) in exterior: return True
            if (r,c) in checked: return (r,c) not in interior or (r,c) in exterior
            stack = [(r,c)]
            component = set()
            is_ext = False
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in component: continue
                if (cr, cc) in border_cells: continue
                if cr < 0 or cr >= rows or cc < 0 or cc >= cols:
                    is_ext = True
                    continue
                if grid[cr][cc] == color: continue  # treat same-color as wall
                component.add((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    stack.append((cr+dr, cc+dc))
            checked.update(component)
            if is_ext:
                exterior.update(component)
            return is_ext

        true_interior = set()
        for (r,c) in interior:
            if not is_exterior(r,c) and (r,c) not in border_cells:
                true_interior.add((r,c))

        return true_interior

    processed = set()
    shapes = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r,c) not in processed:
                color = grid[r][c]
                border = get_border_cells(r, c, color)
                processed.update(border)
                interior = flood_fill_interior(border, color)
                if interior:
                    # Count non-zero non-border-color values inside
                    val_counts = {}
                    for (ir, ic) in interior:
                        v = grid[ir][ic]
                        if v != 0 and v != color:
                            val_counts[v] = val_counts.get(v, 0) + 1
                    fill_val = None
                    if val_counts:
                        fill_val = max(val_counts, key=val_counts.get)
                    shapes.append((border, interior, color, fill_val))

    # Build output
    for border, interior, color, fill_val in shapes:
        for (r,c) in border:
            out[r][c] = color
        if fill_val and interior:
            for (r,c) in interior:
                out[r][c] = fill_val

    return out

