    # Find rectangle color and cross color
    colors = set(g.flatten()) - {0}

    # Find the rectangle border (has cells forming a closed rectangle)
    for c in colors:
        positions = list(zip(*np.where(g == c)))
        r_vals = sorted(set(p[0] for p in positions))
        c_vals = sorted(set(p[1] for p in positions))
        # Check if forms rectangle border
        if len(r_vals) >= 2 and len(c_vals) >= 2:
            rmin, rmax = r_vals[0], r_vals[-1]
            cmin, cmax = c_vals[0], c_vals[-1]
            is_rect = True
            for r in range(rmin, rmax+1):
                for cc in range(cmin, cmax+1):
                    if r == rmin or r == rmax or cc == cmin or cc == cmax:
                        if g[r][cc] != c:
                            is_rect = False
            if is_rect:
                rect_color = c
                break

    cross_color = (colors - {rect_color}).pop()

    # Find cross lines
    cross_positions = list(zip(*np.where(g == cross_color)))
    cross_row = cross_positions[0][0]  # horizontal line row
    cross_col = cross_positions[0][1]  # vertical line col
    for r, c in cross_positions:
        if sum(1 for rr, cc in cross_positions if cc == c) > sum(1 for rr, cc in cross_positions if cc == cross_col):
            cross_col = c
        if sum(1 for rr, cc in cross_positions if rr == r) > sum(1 for rr, cc in cross_positions if rr == cross_row):
            cross_row = r

    # Determine which edge each line moves to
    dist_left = cross_col - cmin
    dist_right = cmax - cross_col
    new_col = cmin if dist_left >= dist_right else cmax

    dist_top = cross_row - rmin
    dist_bottom = rmax - cross_row
    new_row = rmax if dist_bottom >= dist_top else rmin

    # Build output
    out = np.zeros_like(g)

    # Draw rectangle border
    for r in range(rmin, rmax+1):
        for c in range(cmin, cmax+1):
            if r == rmin or r == rmax or c == cmin or c == cmax:
                out[r][c] = rect_color

    # Draw relocated cross lines outside rectangle
    # Vertical line at new_col, only outside rectangle rows
    for r in range(rows):
        if r < rmin or r > rmax:
            out[r][new_col] = cross_color

    # Horizontal line at new_row, only outside rectangle cols
    for c in range(cols):
        if c < cmin or c > cmax:
            out[new_row][c] = cross_color

    return out.tolist()

