    # Find all crosses
    crosses = []
    for r in range(1, rows-1):
        for c in range(1, cols-1):
            if grid[r-1][c]==3 and grid[r+1][c]==3 and grid[r][c-1]==3 and grid[r][c+1]==3:
                crosses.append((r, c, grid[r][c]))

    colored = [(r,c,v) for r,c,v in crosses if v != 0]
    empty = [(r,c) for r,c,v in crosses if v == 0]

    # Track all 3-positions belonging to crosses
    cross_3s = set()
    for r,c,v in crosses:
        cross_3s.update([(r-1,c),(r+1,c),(r,c-1),(r,c+1)])

    empty_cols = set(c for r,c in empty)

    # Horizontal lines first
    for cr, cc, cv in colored:
        # Extend right from right arm
        for c2 in range(cc+2, cols):
            if c2 in empty_cols:
                continue
            if (cr, c2) in cross_3s:
                # It's another cross's arm - check if it's not our own
                is_own = False
                for r2,c2b,v2 in crosses:
                    if (r2,c2b) == (cr,cc):
                        continue
                    if (cr,c2) in [(r2-1,c2b),(r2+1,c2b),(r2,c2b-1),(r2,c2b+1)]:
                        is_own = False
                        break
                break  # stop at any cross arm
            out[cr][c2] = cv
        # Extend left from left arm
        for c2 in range(cc-2, -1, -1):
            if c2 in empty_cols:
                continue
            if (cr, c2) in cross_3s:
                break
            out[cr][c2] = cv

    # Vertical lines (overwrite horizontal)
    for cr, cc, cv in colored:
        for r2 in range(rows):
            if r2 == cr-1 or r2 == cr+1:
                continue  # preserve arms (3s)
            if r2 == cr:
                continue  # preserve center
            out[r2][cc] = cv

    return out

