def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)

    # Find all crosses: center at (r,c) with 3s at all 4 cardinal neighbors
    crosses = []
    for r in range(1, rows-1):
        for c in range(1, cols-1):
            if grid[r-1][c]==3 and grid[r+1][c]==3 and grid[r][c-1]==3 and grid[r][c+1]==3:
                crosses.append((r, c, grid[r][c]))

    # Collect all 3-positions belonging to each cross
    cross_3s = {}
    for r, c, color in crosses:
        cross_3s[(r,c)] = {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}

    all_3_positions = set()
    for s in cross_3s.values():
        all_3_positions |= s

    # For each cross, cast rays in 4 directions, store horizontal and vertical ray maps
    h_rays = {}  # (row, col) -> color from horizontal ray
    v_rays = {}  # (row, col) -> color from vertical ray

    for r, c, color in crosses:
        own_3s = cross_3s[(r,c)]
        # Up
        for rr in range(r-1, -1, -1):
            if (rr, c) in all_3_positions and (rr, c) not in own_3s:
                break
            v_rays[(rr, c)] = color
        # Down
        for rr in range(r+1, rows):
            if (rr, c) in all_3_positions and (rr, c) not in own_3s:
                break
            v_rays[(rr, c)] = color
        # Left
        for cc in range(c-1, -1, -1):
            if (r, cc) in all_3_positions and (r, cc) not in own_3s:
                break
            h_rays[(r, cc)] = color
        # Right
        for cc in range(c+1, cols):
            if (r, cc) in all_3_positions and (r, cc) not in own_3s:
                break
            h_rays[(r, cc)] = color
        # Center
        v_rays[(r, c)] = color
        h_rays[(r, c)] = color

    # Build output
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                output[r][c] = 3
            elif (r, c) in v_rays and (r, c) in h_rays:
                output[r][c] = v_rays[(r, c)]  # vertical wins
            elif (r, c) in v_rays:
                output[r][c] = v_rays[(r, c)]
            elif (r, c) in h_rays:
                output[r][c] = h_rays[(r, c)]
            else:
                output[r][c] = 0

    return output

