def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}

    color_map = {(0,0):2, (1,0):3, (0,1):4, (1,1):5}  # missing corner → color

    result = [[0]*cols for _ in range(rows)]

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        r, c = cell
        # Try 2x2 block
        block = {(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if block <= remaining:
            rest = solve(remaining - block)
            if rest is not None:
                return [('block', block)] + rest
        # Try L-triominoes (3 cells of a 2x2)
        for dr in range(2):
            for dc in range(2):
                tr, tc = r - dr, c - dc
                full = {(tr+i,tc+j) for i in range(2) for j in range(2)}
                for mr in range(2):
                    for mc in range(2):
                        missing = (tr+mr, tc+mc)
                        tri = full - {missing}
                        if cell in tri and tri <= remaining:
                            rest = solve(remaining - tri)
                            if rest is not None:
                                return [('L', tri, mr, mc)] + rest
        return None

    pieces = solve(cells)

    for piece in pieces:
        if piece[0] == 'block':
            for (r,c) in piece[1]:
                result[r][c] = 1
        else:
            _, tri, mr, mc = piece
            color = color_map[(mr, mc)]
            for (r,c) in tri:
                result[r][c] = color

    return result

