    def flood_fill(r, c, val):
        if r<0 or r>=rows or c<0 or c>=cols or visited[r][c] or grid[r][c]!=val:
            return []
        visited[r][c] = True
        cells = [(r,c)]
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            cells.extend(flood_fill(r+dr, c+dc, val))
        return cells

    seven_groups, one_groups = [], []
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                if grid[r][c]==7: seven_groups.append(flood_fill(r,c,7))
                elif grid[r][c]==1: one_groups.append(flood_fill(r,c,1))

    def get_color(cells):
        mr, mc = min(r for r,c in cells), min(c for r,c in cells)
        pos = set((r-mr, c-mc) for r,c in cells)
        missing = ({(0,0),(0,1),(1,0),(1,1)} - pos).pop()
        return {(0,0):3, (0,1):5, (1,0):4, (1,1):6}[missing]

    output = [[0]*cols for _ in range(rows)]
    used = set()
    for sg in seven_groups:
        color = get_color(sg)
        best, best_dist = None, float('inf')
