                    if d < best_dist: best_dist, best = d, i
        if best is not None:
            used.add(best)
            for r,c in one_groups[best]: output[r][c] = color
    return output

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[0]*cols for _ in range(rows)]

    def find_components(val, eight=False):
        visited = set()
        comps = []
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]
        if eight:
            dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == val and (r,c) not in visited:
                    comp = []
                    queue = [(r,c)]
                    visited.add((r,c))
                    while queue:
                        cr,cc = queue.pop(0)
                        comp.append((cr,cc))
                        for dr,dc in dirs:
                            nr,nc = cr+dr, cc+dc
                            if 0<=nr<rows and 0<=nc<cols and (nr,nc) not in visited and grid[nr][nc]==val:
                                visited.add((nr,nc))
                                queue.append((nr,nc))
                    comps.append(comp)
        return comps

    seven_comps = find_components(7, eight=False)
    one_comps = find_components(1, eight=True)

    def get_color(comp):
        cells = set(comp)
        min_r = min(r for r,c in comp)
        max_r = max(r for r,c in comp)
        min_c = min(c for r,c in comp)
        max_c = max(c for r,c in comp)
        tl = (min_r, min_c) in cells
        tr = (min_r, max_c) in cells
        bl = (max_r, min_c) in cells
        br = (max_r, max_c) in cells
        if not tl: return 3
        if not bl: return 4
        if not tr: return 5
        if not br: return 6
        return 1

    def min_dist(c1, c2):
        md = float('inf')
        for r1,cc1 in c1:
            for r2,cc2 in c2:
                d = abs(r1-r2)+abs(cc1-cc2)
                if d < md: md = d
        return md

    color_map = {}
    for sc in seven_comps:
        color = get_color(sc)
        best_i, best_d = -1, float('inf')
        for i, oc in enumerate(one_comps):
            d = min_dist(sc, oc)
            if d < best_d:
                best_d = d
                best_i = i
        if best_i >= 0:
            color_map[best_i] = color

    for i, oc in enumerate(one_comps):
        c = color_map.get(i, 1)
        for r, cc in oc:
            output[r][cc] = c

    return output

def transform(grid):
    import numpy as np
    g = np.array(grid)
    colors = [c for c in np.unique(g) if c != 0]

    shapes = {}
    for c in colors:
        positions = list(zip(*np.where(g == c)))
        min_r = min(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_r = max(p[0] for p in positions)
        max_c = max(p[1] for p in positions)
        shape = np.zeros((max_r - min_r + 1, max_c - min_c + 1), dtype=int)
        for r, c2 in positions:
            shape[r - min_r][c2 - min_c] = c
        shapes[c] = {'shape': shape, 'count': len(positions), 'center': ((min_r+max_r)/2, (min_c+max_c)/2)}

    total = sum(s['count'] for s in shapes.values())

    # Find rectangle dimensions
    for h in range(1, total+1):
        if total % h == 0:
            w = total // h
            # Try all placements via brute force
            pass

    # For this specific puzzle structure, use the identified pattern
    sorted_colors = sorted(shapes.keys(), key=lambda c: shapes[c]['count'], reverse=True)
    main = sorted_colors[0]
    ms = shapes[main]['shape']
    h, w = ms.shape

    remaining = [c for c in sorted_colors[1:]]
    total_remaining = sum(shapes[c]['count'] for c in remaining)

    # Extend to rectangle
    for extra_rows in range(0, 5):
        for extra_cols in range(0, 5):
            nh, nw = h + extra_rows, w + extra_cols
            if nh * nw == total:
                result = np.zeros((nh, nw), dtype=int)
                result[:h, :w] = ms
                gaps = list(zip(*np.where(result == 0)))
                if len(gaps) == total_remaining:
                    # Try to fill gaps with remaining shapes
                    # Simple assignment by spatial position
                    remaining_sorted = sorted(remaining, key=lambda c: shapes[c]['center'])
                    gap_groups = []
                    visited = set()
                    for gp in gaps:
                        if gp not in visited:
                            group = []
                            stack = [gp]
                            while stack:
                                p = stack.pop()
                                if p in visited or p not in gaps:
                                    continue
                                visited.add(p)
                                group.append(p)
                                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                                    np2 = (p[0]+dr, p[1]+dc)
                                    if np2 in gaps and np2 not in visited:
                                        stack.append(np2)
                            gap_groups.append(group)

                    gap_groups.sort(key=lambda grp: (sum(p[0] for p in grp)/len(grp), sum(p[1] for p in grp)/len(grp)))
                    remaining_sorted2 = sorted(remaining, key=lambda c: (shapes[c]['center'][0], shapes[c]['center'][1]))

                    size_map = {}
                    for grp in gap_groups:
                        size_map.setdefault(len(grp), []).append(grp)

                    for c in remaining_sorted2:
                        cnt = shapes[c]['count']
                        if cnt in size_map and size_map[cnt]:
                            grp = size_map[cnt].pop(0)
                            for r, c2 in grp:
                                result[r][c2] = c

                    return result.tolist()

    return grid

