from itertools import product

def transform(grid):
    grid = np.array(grid)
    colors = [c for c in np.unique(grid) if c != 0]
    shapes = {}
    for c in colors:
        pos = list(zip(*np.where(grid == c)))
        mr, mc = min(r for r,_ in pos), min(c2 for _,c2 in pos)
        shapes[c] = [(r-mr, c2-mc) for r,c2 in pos]

    def rotations(cells):
        rots = []
        cur = cells
        for _ in range(4):
            norm = [(r - min(r2 for r2,_ in cur), c - min(c2 for _,c2 in cur)) for r,c in cur]
            norm = tuple(sorted(norm))
            if norm not in rots:
                rots.append(norm)
            cur = [(c, -r) for r,c in cur]
        return rots

    all_rots = {c: rotations(s) for c, s in shapes.items()}
    total = sum(len(s) for s in shapes.values())

    for H in range(1, total+1):
        W = total // H
        if H * W != total:
            continue
        color_list = list(shapes.keys())

        def solve(idx, filled):
            if idx == len(color_list):
                return len(filled) == total, {}
            c = color_list[idx]
            for rot in all_rots[c]:
                max_r = max(r for r,_ in rot)
                max_c = max(c2 for _,c2 in rot)
                for dr in range(H - max_r):
                    for dc in range(W - max_c):
                        placed = set()
                        ok = True
                        for r, c2 in rot:
                            p = (r+dr, c2+dc)
                            if p in filled:
                                ok = False
                                break
                            placed.add(p)
                        if ok:
                            new_filled = filled | placed
                            success, assignment = solve(idx+1, new_filled)
                            if success:
                                assignment[c] = [(r+dr, c2+dc) for r,c2 in rot]
                                return True, assignment
            return False, {}

        success, assignment = solve(0, set())
        if success:
            result = [[0]*W for _ in range(H)]
            for c, positions in assignment.items():
                for r, c2 in positions:
                    result[r][c2] = c
            return result
    return grid.tolist()

