    def rotate90(m):
        h,w=len(m),len(m[0])
        return [[m[h-1-j][i] for j in range(h)] for i in range(w)]

    def get_superblock(bgrid, brows, bcols, sh, sw):
        sbr, sbc = brows//sh, bcols//sw
        sb = [[0]*(sbc) for _ in range(sbr)]
        for i in range(sbr):
            for j in range(sbc):
                sb[i][j] = 1 if all(bgrid[i*sh+di][j*sw+dj] for di in range(sh) for dj in range(sw)) else (0 if all(bgrid[i*sh+di][j*sw+dj]==0 for di in range(sh) for dj in range(sw)) else -1)
        return sb

    cur_key = [row[:] for row in key]
    for rot in range(4):
        ckh, ckw = len(cur_key), len(cur_key[0])
        if brows % ckh == 0 and bcols % ckw == 0:
            sh, sw = brows//ckh, bcols//ckw
