    shape_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in (0,5):
                if not (pr0<=r<=pr1 and pc0<=c<=pc1):
                    shape_color = grid[r][c]
                    break
        if shape_color: break

    # Find connected components (BFS)
    visited = [[False]*cols for _ in range(rows)]
