    max_val = max(max(row) for row in grid)
    p = max_val

    # Reconstruct base tile using majority vote
    tile = [[0]*p for _ in range(p)]
    for tr in range(p):
        for tc in range(p):
            counts = {}
            for kr in range(tr, rows, p):
                for kc in range(tc, cols, p):
                    v = grid[kr][kc]
                    counts[v] = counts.get(v, 0) + 1
            tile[tr][tc] = max(counts, key=counts.get)

    # Tile the entire grid with the reconstructed pattern
    output = [[tile[r % p][c % p] for c in range(cols)] for r in range(rows)]
    return output

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    best, best_count = None, 0
    for r0 in range(rows - 3):
        for c0 in range(cols - 3):
            count = sum(1 for dr in range(4) for dc in range(4) if grid[r0+dr][c0+dc] != 0)
            if count > best_count:
                best_count, best = count, (r0, c0)
    r0, c0 = best
    pattern = [[grid[r0+i][c0+j] for j in range(4)] for i in range(4)]
    pattern_cells = {(r0+i, c0+j) for i in range(4) for j in range(4)}
    markers = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != 0 and (r,c) not in pattern_cells]
    right_map, bottom_map, diag_map = {}, {}, {}
    for mr, mc, mv in markers:
        if r0 <= mr <= r0+3 and mc >= c0+4:
            right_map[pattern[mr-r0][3-(mc-(c0+4))]] = mv
        elif mr >= r0+4 and c0 <= mc <= c0+3:
            bottom_map[pattern[3-(mr-(r0+4))][mc-c0]] = mv
        elif mr >= r0+4 and mc >= c0+4:
            diag_map[pattern[3-(mr-(r0+4))][3-(mc-(c0+4))]] = mv
    output = [row[:] for row in grid]
    for i in range(4):
        for j in range(4):
            output[r0+i][c0+4+j] = right_map.get(pattern[i][3-j], 0)
            output[r0+4+i][c0+j] = bottom_map.get(pattern[3-i][j], 0)
            output[r0+4+i][c0+4+j] = diag_map.get(pattern[3-i][3-j], 0)
    return output

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[5]*cols for _ in range(rows)]

    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r][c] != 0:
                val = grid[r][c]
                start = c
                while c < cols and grid[r][c] == val:
                    c += 1
                # Shift segment left by 1
                new_start = max(0, start - 1)
                new_end = max(0, c - 1)
                for j in range(new_start, new_end):
                    output[r][j] = val
            else:
                c += 1
    return output

def transform(grid):
    nrows, ncols = len(grid), len(grid[0])
    sep_rows = {i for i in range(nrows) if all(grid[i][j] == 0 for j in range(ncols))}
    sep_cols = {j for j in range(ncols) if all(grid[i][j] == 0 for i in range(nrows))}

    row_groups, current = [], []
    for i in range(nrows):
        if i in sep_rows:
            if current: row_groups.append(current); current = []
        else: current.append(i)
    if current: row_groups.append(current)

    col_blocks, current = [], []
    for j in range(ncols):
        if j in sep_cols:
            if current: col_blocks.append(current); current = []
        else: current.append(j)
    if current: col_blocks.append(current)

    rg = row_groups[0]
    patterns, colors = [], []
    for cb in col_blocks:
        pattern, color = [], 0
        for i in rg:
            row_p = []
            for j in cb:
                if grid[i][j] != 0:
                    color = grid[i][j]
                    row_p.append(1)
                else:
                    row_p.append(0)
            pattern.append(row_p)
        patterns.append(pattern)
        colors.append(color)

    shift = len(row_groups) % len(col_blocks)
    out_rows = len(rg)
    output = [[0] * ncols for _ in range(out_rows)]

    for b_idx, cb in enumerate(col_blocks):
        src = (b_idx + shift) % len(col_blocks)
        for ri in range(out_rows):
            for ci, j in enumerate(cb):
                output[ri][j] = colors[b_idx] if patterns[src][ri][ci] == 1 else 0

    return output
